        Vector_2 pr = r - p;

        // Compute the cross product of pq and pr
        auto cross_product = pq.x() * pr.y() - pq.y() * pr.x();

        // Determine the orientation based on the sign of the cross product
        if (cross_product > 0) {
            return CGAL::LEFT_TURN;
        } else if (cross_product < 0) {
            return CGAL::RIGHT_TURN;
        } else {
            return CGAL::COLLINEAR;
        }

